-- Permission vocabulary and system roles of the integrations module
-- Generated by metaphor-schema
--
-- Writes into the identity module's tables (public.permissions, public.roles,
-- public.role_permissions), so those migrations must have run first. Inserts what is
-- missing and never deletes or revokes: what a tenant changed survives a re-run.

DO $$
BEGIN
    IF to_regclass('public.permissions') IS NULL
       OR to_regclass('public.roles') IS NULL
       OR to_regclass('public.role_permissions') IS NULL THEN
        RAISE NOTICE 'seed of the integrations permissions skipped: the identity module has not created public.permissions, public.roles and public.role_permissions';
        RETURN;
    END IF;

    UPDATE public.permissions p SET description = v.description
      FROM (VALUES
            ('integration_connector:create'::text, 'integration_connector'::text, 'create'::text, 'Create integration connector'::text),
            ('integration_connector:delete'::text, 'integration_connector'::text, 'delete'::text, 'Delete integration connector'::text),
            ('integration_connector:purge'::text, 'integration_connector'::text, 'purge'::text, 'Purge integration connector'::text),
            ('integration_connector:read'::text, 'integration_connector'::text, 'read'::text, 'Read integration connector'::text),
            ('integration_connector:restore'::text, 'integration_connector'::text, 'restore'::text, 'Restore integration connector'::text),
            ('integration_connector:update'::text, 'integration_connector'::text, 'update'::text, 'Update integration connector'::text),
            ('integration_event:create'::text, 'integration_event'::text, 'create'::text, 'Create integration event'::text),
            ('integration_event:delete'::text, 'integration_event'::text, 'delete'::text, 'Delete integration event'::text),
            ('integration_event:purge'::text, 'integration_event'::text, 'purge'::text, 'Purge integration event'::text),
            ('integration_event:read'::text, 'integration_event'::text, 'read'::text, 'Read integration event'::text),
            ('integration_event:restore'::text, 'integration_event'::text, 'restore'::text, 'Restore integration event'::text),
            ('integration_event:update'::text, 'integration_event'::text, 'update'::text, 'Update integration event'::text)
      ) AS v(name, resource, action, description)
     WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL
       AND p.description IS DISTINCT FROM v.description;

    INSERT INTO public.permissions (name, resource, action, description)
    SELECT v.name, v.resource, v.action, v.description
      FROM (VALUES
            ('integration_connector:create'::text, 'integration_connector'::text, 'create'::text, 'Create integration connector'::text),
            ('integration_connector:delete'::text, 'integration_connector'::text, 'delete'::text, 'Delete integration connector'::text),
            ('integration_connector:purge'::text, 'integration_connector'::text, 'purge'::text, 'Purge integration connector'::text),
            ('integration_connector:read'::text, 'integration_connector'::text, 'read'::text, 'Read integration connector'::text),
            ('integration_connector:restore'::text, 'integration_connector'::text, 'restore'::text, 'Restore integration connector'::text),
            ('integration_connector:update'::text, 'integration_connector'::text, 'update'::text, 'Update integration connector'::text),
            ('integration_event:create'::text, 'integration_event'::text, 'create'::text, 'Create integration event'::text),
            ('integration_event:delete'::text, 'integration_event'::text, 'delete'::text, 'Delete integration event'::text),
            ('integration_event:purge'::text, 'integration_event'::text, 'purge'::text, 'Purge integration event'::text),
            ('integration_event:read'::text, 'integration_event'::text, 'read'::text, 'Read integration event'::text),
            ('integration_event:restore'::text, 'integration_event'::text, 'restore'::text, 'Restore integration event'::text),
            ('integration_event:update'::text, 'integration_event'::text, 'update'::text, 'Update integration event'::text)
      ) AS v(name, resource, action, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

END $$;
